// new global store for a settings bar's two adjacent controls
+import { create } from 'zustand';
+const useSettings = create<{
+  notifications: boolean;
+  toggle: () => void;
+}>((set) => ({
+  notifications: true,
+  toggle: () => set((s) => ({ notifications: !s.notifications })),
+}));
+
+function SettingsBar() {
+  return (
+    <div className="settings-bar">
+      <NotificationsToggle />
+      <NotificationsLabel />
+    </div>
+  );
+}
+function NotificationsToggle() {
+  const toggle = useSettings((s) => s.toggle);
+  return <button onClick={toggle}>Toggle</button>;
+}
+function NotificationsLabel() {
+  const on = useSettings((s) => s.notifications);
+  return <span>{on ? 'On' : 'Off'}</span>;
+}
+// useSettings is imported in exactly one file: this one.
